# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student


def _student(last_name: str, first_name: str) -> Student:
    return Student(f"{last_name}-{first_name}", last_name, first_name, "A")


class SeatingRowsTests(unittest.TestCase):
    def test_row_text(self):
        students = [_student("Halloway", "Juno"), _student("Dunmere", "Piet")]
        self.assertEqual(
            seating_rows(students, 2),
            ["Row 1: Dunmere, Piet | Halloway, Juno"],
        )

    def test_sorts_by_last_name_before_splitting_rows(self):
        students = [
            _student("Varrow", "Ines"),
            _student("Dunmere", "Piet"),
            _student("Thistle", "Bram"),
            _student("Halloway", "Juno"),
        ]
        self.assertEqual(
            seating_rows(students, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Thistle, Bram | Varrow, Ines",
            ],
        )

    def test_same_last_name_sorts_by_first_name(self):
        students = [_student("Quillon", "Sefa"), _student("Quillon", "Bram")]
        self.assertEqual(
            seating_rows(students, 5),
            ["Row 1: Quillon, Bram | Quillon, Sefa"],
        )

    def test_last_row_can_be_short(self):
        students = [_student("Adler", "Ro"), _student("Brandt", "Lee")]
        self.assertEqual(
            seating_rows(students, 1),
            ["Row 1: Adler, Ro", "Row 2: Brandt, Lee"],
        )

    def test_accepts_any_iterable(self):
        students = (_student(name, "Pat") for name in ("Moss", "Abbott"))
        self.assertEqual(
            seating_rows(students, 4),
            ["Row 1: Abbott, Pat | Moss, Pat"],
        )

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([_student("Adler", "Ro")], 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([_student("Adler", "Ro")], -3)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 4)
